// codexThreadIdentity binds this ephemeral native turn to one declared thread.
// It deliberately does not change the older ParseStreams/Mu contract. Replayed
// declarations of the same identity are idempotent; a later writer cannot
// replace the first identity or retroactively bind an earlier message/turn.
func codexThreadIdentity(stdout []byte)(string,bool){
 thread:=""
 for _,line:=range bytes.Split(stdout,[]byte("\n")){
  if len(bytes.TrimSpace(line))==0{continue}
  var row map[string]any
  if !utf8.Valid(line)||json.Unmarshal(line,&row)!=nil{return "",false}
  kind,_:=row["type"].(string)
  if kind=="thread.started"{
   id,ok:=row["thread_id"].(string)
   if !ok||id==""||strings.TrimSpace(id)!=id||utf8.RuneCountInString(id)>256{return "",false}
   for _,r:=range id{if unicode.IsControl(r){return "",false}}
   if thread!=""&&id!=thread{return "",false}
   thread=id
  }else{
   if (strings.HasPrefix(kind,"item.")||strings.HasPrefix(kind,"turn."))&&thread==""{return "",false}
   if value,exists:=row["thread_id"];exists&&value!=thread{return "",false}
  }
 }
 return thread,thread!=""
}

